Here's an example code to remove duplicates from a linked list in C++:

```
#include <iostream>
#include <unordered_set>

using namespace std;

struct Node {
    int data;
    Node* next;
    Node(int val) : data(val), next(nullptr) {}
};

void removeDuplicates(Node* head) {
    unordered_set<int> seen;
    Node* prev = nullptr;
    Node* curr = head;

    while (curr != nullptr) {
        if (seen.count(curr->data)) {
            prev->next = curr->next;
            delete curr;
        } else {
            seen.insert(curr->data);
            prev = curr;
        }
        curr = prev->next;
    }
}

void printList(Node* head) {
    while (head != nullptr) {
        cout << head->data << " ";
        head = head->next;
    }
    cout << endl;
}

int main() {
    Node* head = new Node(1);
    head->next = new Node(2);
    head->next->next = new Node(3);
    head->next->next->next = new Node(2);
    head->next->next->next->next = new Node(4);
    head->next->next->next->next->next = new Node(1);

    cout << "Original list: ";
    printList(head);

    removeDuplicates(head);

    cout << "List after removing duplicates: ";
    printList(head);

    return 0;
}
```

In this example, we use an unordered set to keep track of values that have already been seen. We iterate through the linked list, and if we encounter a node with a value that has already been seen, we delete that node by changing the 'next' pointers of the previous node and the current node. If a value has not been seen before, we insert it into the set and move to the next node.

