```c++
#include <iostream>
#include <vector>

using namespace std;

// Merge two sorted subarrays into one sorted array
void merge(vector<int>& arr, int low, int mid, int high) {
    // Create temporary arrays for left and right subarrays
    vector<int> left(mid - low + 1);
    vector<int> right(high - mid);

    // Copy data from arr to temporary arrays
    for (int I = 0; I < left.size(); i++) {
        left[i] = arr[low + i];
    }
    for (int I = 0; I < right.size(); i++) {
        right[i] = arr[mid + 1 + i];
    }

    // Merge the temporary arrays back into arr
    int I = 0; // Index of left subarray
    int j = 0; // Index of right subarray
    int k = low; // Index of merged array
    while (i < left.size() && j < right.size()) {
        if (left[i] <= right[j]) {
            arr[k] = left[i];
            i++;
        } else {
            arr[k] = right[j];
            j++;
        }
        k++;
    }

    // Copy any remaining elements of left subarray
    while (i < left.size()) {
        arr[k] = left[i];
        i++;
        k++;
    }

    // Copy any remaining elements of right subarray
    while (j < right.size()) {
        arr[k] = right[j];
        j++;
        k++;
    }
}

// Recursive function to sort subarrays of arr
void mergeSort(vector<int>& arr, int low, int high) {
    if (low < high) {
        int mid = (low + high) / 2; // Find middle index
        mergeSort(arr, low, mid); // Sort left subarray
        mergeSort(arr, mid + 1, high); // Sort right subarray
        merge(arr, low, mid, high); // Merge left and right subarrays
    }
}

// Function to sort an array using merge sort
void sortArray(vector<int>& arr) {
    // Call mergeSort function to sort array
    mergeSort(arr, 0, arr.size() - 1);
}

int main() {
    // Take input array from user
    int n;
    cout << "Enter number of elements: ";
    cin >> n;
    vector<int> arr(n);
    cout << "Enter " << n << " elements: ";
    for (int I = 0; I < n; i++) {
        cin >> arr[i];
    }

    // Sort the array using merge sort
    sortArray(arr);

    // Print sorted array
    cout << "Sorted array: ";
    for (int I = 0; I < n; i++) {
        cout << arr[i] << " ";
    }
    cout << endl;

    return 0;
}
```

Explanation:

- The `merge` function takes an array `arr` and three integer parameters `low`, `mid`, and `high` that specify the indices of the left subarray (`arr[low...mid]`) and right subarray (`arr[mid+1...high]`) to be merged. It creates two temporary subarrays (`left` and `right`) and copies the elements from the corresponding subarrays in `arr` to them. It then iterates through both subarrays (`left` and `right`) simultaneously, comparing the elements and copying the smaller one to the merged array (`arr`). After the two subarrays are exhausted, any remaining elements from the `left` or `right` subarray are copied to `arr`. This results in a sorted array (`arr[low...high]`).
- The `mergeSort` function is recursive and takes an array `arr` and two integer parameters `low` and `high` that specify the bounds of the subarray to be sorted (`arr[low...high]`). It continues recursively breaking down the subarrays into smaller subarrays until each subarray has at most one element. Then, it merges the smaller subarrays together in sorted order using the `merge` function. The end result is a fully sorted array (`arr[low...high]`).
- The `sortArray` function takes an array `arr` and simply calls the `mergeSort` function to sort the entire array (`arr[0...n-1]`).
- The `main` function first takes input from the user, creates an array `arr` of size `n`, and populates it with the user's input. It then calls the `sortArray` function to sort the array, and finally prints the sorted array to the console.

